"""Shared configuration, file paths and JSON helpers.

Credentials are read from ``config.ini`` (copy ``default_config.ini`` and fill
it in). All paths are resolved relative to this folder, so the scripts work no
matter which directory they are launched from.
"""

import configparser
import json
from pathlib import Path

import spotipy

BASE_DIR = Path(__file__).resolve().parent

CONFIG_PATH = BASE_DIR / "config.ini"
USERS_PATH = BASE_DIR / "users.json"  # optional: friends to scrape (see README)

# Generated by gen_lists.py, consumed by bot.py / cli_quiz.py
SONG_LIST_PATH = BASE_DIR / "songlist.json"
PEOPLE_LIST_PATH = BASE_DIR / "people_list.json"
PLAYLIST_LIST_PATH = BASE_DIR / "playlist_list.json"
NORMALISED_LIST_PATH = BASE_DIR / "normalised_list.json"

SPOTIPY_REDIRECT_URI = "http://127.0.0.1:8080"

# Discord server the slash commands are registered to, if not set in config.ini
# DEFAULT_GUILD_ID = "830237925303517255"
DEFAULT_GUILD_ID = "965730825750581288"

_config = configparser.ConfigParser()
_config.read(CONFIG_PATH)


def get_cred(key: str, fallback: str | None = None) -> str:
    """Return a value from the ``[creds]`` section of config.ini.

    Missing or blank values return ``fallback``, or raise if there is none.
    """
    value = _config.get("creds", key, fallback=None) or fallback
    if not value:
        raise KeyError(f"'{key}' is missing from the [creds] section of {CONFIG_PATH}")
    return value


def spotify_client(scope: str | None = None) -> spotipy.Spotify:
    """Create an authenticated Spotify Web API client (opens a browser on first run)."""
    return spotipy.Spotify(
        auth_manager=spotipy.SpotifyOAuth(
            client_id=get_cred("SPOTIPY_CLIENT_ID"),
            client_secret=get_cred("SPOTIPY_CLIENT_SECRET"),
            redirect_uri=SPOTIPY_REDIRECT_URI,
            scope=scope,
            cache_path=str(BASE_DIR / ".cache"),
        )
    )


def load_json(path: Path):
    with open(path, encoding="utf-8") as f:
        return json.load(f)


def save_json(path: Path, data) -> None:
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=4)
